#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>

int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char *path = NULL;
    FILE *fp;
    size_t var_len = strlen(var);
    size_t iface_len = strlen(iface);

    // Check for path traversal attempts in the interface name
    if (strchr(iface, '/') != NULL) {
        fprintf(stderr, "Invalid interface name: %s\n", iface);
        return -1;
    }

    // Allocate memory for the path
    path = malloc(var_len + iface_len + 1);
    if (!path) {
        perror("Failed to allocate memory");
        return -1;
    }

    // Format the path using the variable format and interface name
    snprintf(path, var_len + iface_len + 1, var, iface);

    // Open the file for writing
    fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open file");
        free(path);
        return -1;
    }

    // Write the value to the file
    if (fprintf(fp, "%u", val) < 0) {
        perror("Failed to write to file");
        fclose(fp);
        free(path);
        return -1;
    }

    // Close the file and free resources
    fclose(fp);
    free(path);
    return 0;
}

