#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>

int set_iface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[256];
    int len = snprintf(path, sizeof(path), var, iface);

    if (len < 0 || len >= sizeof(path)) {
        return -1;
    }

    if (strnstr(path, "../", sizeof(path)) != NULL) {
        return -1;
    }

    FILE *fp = fopen(path, "w");
    if (!fp) {
        return -1;
    }

    if (fprintf(fp, "%u", val) < 0) {
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}
